result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "wfc.py", "content": """"Tiny wave-function-collapse over three terrain tiles.

Tiles: SEA (~), COAST (+), LAND (#)
Adjacency rules (orthogonal neighbours):
    SEA-SEA, SEA-COAST, COAST-COAST, COAST-LAND, LAND-LAND allowed.
    SEA never touches LAND.
"""

from __future__ import annotations

import random

SEA, COAST, LAND = "SEA", "COAST", "LAND"
TILES = (SEA, COAST, LAND)

_ALLOWED = {
    (SEA, SEA), (SEA, COAST), (COAST, SEA),
    (COAST, COAST), (COAST, LAND), (LAND, COAST),
    (LAND, LAND),
}

GLYPH = {SEA: "~", COAST: "+", LAND: "#"}

MAX_RESTARTS = 50


def _neighbours(r: int, c: int, h: int, w: int):
    if r > 0:
        yield r - 1, c
    if r < h - 1:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c < w - 1:
        yield r, c + 1


def _propagate(domains, queue, h, w):
    """Arc-consistency propagation. Returns False on contradiction."""
    while queue:
        cell = queue.pop()
        r, c = cell
        d_here = domains[r][c]
        if not d_here:
            return False
        for nr, nc in _neighbours(r, c, h, w):
            d_nb = domains[nr][nc]
            if len(d_nb) == 1:
                continue
            supported = {
                t2 for t2 in d_nb
                if any((t1, t2) in _ALLOWED for t1 in d_here)
            }
            if not supported:
                return False
            if supported != d_nb:
                domains[nr][nc] = supported
                queue.add((nr, nc))
    return True


def _attempt(h: int, w: int, rng: random.Random):
    """One collapse attempt. Returns grid dict {(r,c): tile} or None."""
    full = frozenset(TILES)
    domains = [[full] * w for _ in range(h)]
    uncollapsed = {(r, c) for r in range(h) for c in range(w)}

    while uncollapsed:
        # Minimum-entropy cell selection (random tie-break, deterministic).
        best = None
        best_entropy = None
        best_key = None
        for cell in sorted(uncollapsed):  # sorted -> stable scan order
            entropy = len(domains[cell[0]][cell[1]])
            key = rng.random()
            if best_entropy is None or entropy < best_entropy:
                best, best_entropy, best_key = cell, entropy, key

        r, c = best
        options = sorted(domains[r][c])
        choice = rng.choice(options)
        domains[r][c] = frozenset((choice,))
        uncollapsed.discard(best)

        if not _propagate(domains, {best}, h, w):
            return None

        # Freeze fully-collapsed neighbours reached by propagation.
        for rr in range(h):
            for cc in range(w):
                if len(domains[rr][cc]) == 1 and (rr, cc) in uncollapsed:
                    uncollapsed.discard((rr, cc))

    return [[next(iter(domains[r][c])) for c in range(w)] for r in range(h)]


def collapse(h: int = 20, w: int = 20, seed: int = 0):
    """Collapse an h x w grid. Restarts on contradiction (max 50).

    Returns the finished grid as a list of row lists of tile names.
    Raises RuntimeError if every attempt ends in contradiction.
    """
    rng = random.Random(seed)
    for _ in range(MAX_RESTARTS):
        grid = _attempt(h, w, rng)
        if grid is not None:
            return grid
    raise RuntimeError(f"collapse failed after {MAX_RESTARTS} restarts (seed={seed})")


def render(grid) -> str:
    """ASCII art of a finished grid."""
    return "\n".join("".join(GLYPH[t] for t in row) for row in grid)


if __name__ == "__main__":
    g = collapse(seed=1)
    print(render(g))
"})
