result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_wfc.py", "content": "import wfc


def _allowed_pair(a, b):
    return (a, b) in wfc._ALLOWED


def test_no_adjacency_violations_for_seeds_1_to_20():
    for seed in range(1, 21):
        grid = wfc.collapse(20, 20, seed=seed)
        assert len(grid) == 20 and all(len(row) == 20 for row in grid)
        for r in range(20):
            for c in range(20):
                if r + 1 < 20:
                    assert _allowed_pair(grid[r][c], grid[r + 1][c]), (
                        f"seed={seed} vertical violation at ({r},{c})"
                    )
                if c + 1 < 20:
                    assert _allowed_pair(grid[r][c], grid[r][c + 1]), (
                        f"seed={seed} horizontal violation at ({r},{c})"
                    )


def test_same_seed_reproduces_same_grid():
    for seed in (1, 7, 13):
        assert wfc.collapse(20, 20, seed=seed) == wfc.collapse(20, 20, seed=seed)


def test_some_seed_produces_all_three_tiles():
    found = False
    for seed in range(1, 21):
        grid = wfc.collapse(20, 20, seed=seed)
        used = {t for row in grid for t in row}
        if used == {"SEA", "COAST", "LAND"}:
            found = True
            break
    assert found, "no seed in 1..20 produced all three tile types"


def test_render_ascii():
    out = wfc.render(wfc.collapse(20, 20, seed=1))
    lines = out.splitlines()
    assert len(lines) == 20
    assert set("".join(lines)) <= {"~", "+", "#"}
"})
